grid = [
    [4, 2, 2, 4, 4],
    [4, 2, 2, 4, 4],
    [2, 4, 4, 2, 4],
    [4, 2, 2, 2, 4],
    [4, 4, 2, 4, 4],
    [4, 2, 4, 4, 2],
    [6, 6, 6, 6, 6],
    [7, 4, 4, 7, 7],
    [4, 4, 4, 4, 4],
    [4, 4, 7, 7, 4],
    [7, 4, 4, 7, 7],
    [4, 4, 7, 7, 4],
    [7, 4, 4, 7, 4],
]

bottom = grid[7:]

# Try: bottom section with 7s replaced by 2s and 4s stayed as 4s
output1 = [row[:] for row in bottom]
for r in range(6):
    for c in range(5):
        if bottom[r][c] == 7:
            output1[r][c] = 2

print("Hypothesis 1: Bottom section with 7s->2s")
for row in output1:
    print(row)

# Try: bottom section swapped (4->7, 7->4)
output2 = [row[:] for row in bottom]
for r in range(6):
    for c in range(5):
        if bottom[r][c] == 4:
            output2[r][c] = 7
        else:
            output2[r][c] = 4

print("\nHypothesis 2: Bottom section with 4->7 and 7->4")
for row in output2:
    print(row)

# Maybe the output needs the top section transformed differently
# Let me check if there's a 180 degree rotation involved

def rotate_180(grid_section):
    return [row[::-1] for row in grid_section[::-1]]

top = grid[:6]
top_180 = rotate_180(top)
print("\nTop section rotated 180 degrees:")
for row in top_180:
    print(row)

# What if output is top rotated 180 with 2s->7s?
output3 = [row[:] for row in top_180]
for r in range(6):
    for c in range(5):
        if top_180[r][c] == 2:
            output3[r][c] = 7
        elif top_180[r][c] == 4:
            output3[r][c] = 4

print("\nHypothesis 3: Top rotated 180 with 2s->7s")
for row in output3:
    print(row)

